// TurboQuant combo for -ctk turbo4 -ctv turbo4 (added by hand, not autogenerated by generate_cu_files.py).
// Needed for the nvfp4 competitor gate: turbo4_0 storage (66 B / 128 coords = 0.5156 B/coord) is the PPL rival.
// NOTE: default routing still sends turbo4 combos to the f16-scratch MMA path (GGML_TURBO_DITHER speed gate
// in fattn.cu); this instance only makes the native vec kernel AVAILABLE (GGML_CUDA_FATTN_VEC_NATIVE=1),
// which is the only way turbo4 KV can run past ~8K context on 16 GB (MMA needs a full f16 K/V scratch:
// 8.0 GiB at 32K).  No 64 case: a QK_TURBO4 = 128 block does not fit in a 64-element K row.

#include "../fattn-vec.cuh"

DECL_FATTN_VEC_CASE(128, GGML_TYPE_TURBO4_0, GGML_TYPE_TURBO4_0);
DECL_FATTN_VEC_CASE(256, GGML_TYPE_TURBO4_0, GGML_TYPE_TURBO4_0);
